for (const group of groups) {
  for (const character of group.characters) {
    character.traits = character.traits.map(trait => group.characters.reduce((value, other) => {
      if (other.id !== character.id && other.name.length > 1) return value.replaceAll(other.name, '同伴')
      return value
    }, trait))
  }
}
